content.content:
    /// A family change replaces the style popup's ITEMS, so it has to be part
    /// of the rebuild signature — refreshing alone would leave the old
    /// family's styles listed.
    override var structureSignature: String {
        super.structureSignature + "|" + TextFace.family(of: binding.textProps.font)
    }

    // MARK: Content

    /// The footnote on a word-styled page whose timings a content edit
    /// dropped (road map 8 §5e), and the Animation section's on a styled
    /// page, whose reveal the word style replaces (spec §11 W-5). The second
    /// is short on purpose: its row is 244 pt at the 280 pt narrowest
    /// inspector (`DocumentPane.transparencyNote` has the arithmetic, #70).
    static let untimedNote = "Not timed — regenerate to time it again"
    static let wordStyleNote = "Word style wins; the reveal does not apply."

    func contentSection() -> InspectorSection {
        let binding = self.binding
        let area = InspectorTextArea(
            read: { binding.textProps.content },
            // Per clip: a timed page keeps its words while the count holds
            // and sends `words: []` beside the content when it does not.
            write: { value in binding.apply("Edit Text", binding.ops(textContent: value)) },
            enabled: { !binding.textClips.isEmpty },
            onEdit: { binding.edited() })
        return InspectorSection(
            id: "text.content", title: "Content",
            summary: {
                let line = binding.textProps.content
                    .split(whereSeparator: \.isNewline).first.map(String.init) ?? ""
                return line.isEmpty ? "empty" : line
            },
            note: {
                binding.textProps.isUntimedPage ? Self.untimedNote : nil
            },
                        b.radius = value
                        return ops(b)
                    },
                    mixed: { binding.mixedText { $0.backdrop?.radius } },
                    enabled: on),
            ])
    }

    // MARK: Box

    /// Auto-size or a fixed width that wraps (§4.3). `width` is the model's
    /// three-state field: an explicit null restores auto-sizing, which is why
    /// the patch uses the double optional.
    func boxSection() -> InspectorSection {
        let binding = self.binding
        func fixed() -> Bool { binding.textProps.width != nil }
        func currentWidth() -> Double {
            binding.textProps.width ?? Double(binding.canvas.width) * 0.6
        }
        let mode = OptionPopupControl(
            width: 132, items: ["Auto-size", "Fixed width"],
            read: { fixed() ? 1 : 0 },
            write: { index in
                let patch = TextPatch(width: index == 1 ? .some(currentWidth()) : .some(nil))
                binding.apply("Text Box", text: patch)
            },
            enabled: { true },
            onEdit: { binding.edited() })
        return InspectorSection(
            id: "text.box", title: "Box",
            summary: { fixed() ? String(format: "%.0f px", currentWidth()) : "auto" },
            reset: { binding.apply("Text Box", text: TextPatch(width: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorRow("Mode", [mode], mixed: { binding.mixedText { $0.width != nil } },
                    binding: binding,
                    writes: binding.ops(text: TextPatch(width: .some(binding.textProps.width))),
                    default: .derived(binding, name: "Text Box", read: { binding.textProps.width },
                                      ops: { binding.ops(text: TextPatch(width: .some($0))) })),
                inspectorValueRow(
                    "Width", binding, name: "Text Width", unit: " px", decimals: 0, min: 20,
                    max: 20000, slider: false,
                    read: currentWidth,
                    ops: { binding.ops(text: TextPatch(width: .some($0))) },
                    mixed: { binding.mixedText { $0.width } },
                    enabled: fixed, resets: false),
            ])
    }

    // MARK: Animation

    /// How the words arrive and how they leave (§4.3, format version 5).
    ///
    /// Three controls for three keys: which reveal, how long it takes to
    /// arrive, and how long it takes to leave. The core turns them into one
    /// number per frame — nothing here draws or times anything, and the
    /// section cannot show the reveal's progress, because the progress is a
    /// fact about the frame under the playhead and not about the clip.
    ///
    /// `animation` is a whole OBJECT in the patch, so every row re-sends all
    /// three keys. The core MERGES a nested object key by key (§5.2), but a
    /// stored `null` is not an object — turning the reveal ON replaces the
    /// null with what this patch carries, and a key left out would then come
    /// from the struct's default and silently reset what the user did not
    /// touch. A section that knows all three keys is right in both cases.
    /// Turning the popup to None sends an explicit null, which is the
    /// model's "no animation".
    ///
    /// One thing worth knowing before animating this section from an action:
    /// `in` and `out` are numbers, so an action END patch would interpolate
    /// them and slide the animation's own timebase mid-reveal. The kind is a
    /// string and switches at the end, which is the sane half.
    func animationSection() -> InspectorSection {
        let binding = self.binding
        let kinds = TextAnimationKind.allCases
        let items = ["None"] + kinds.map { $0.displayName }
        func current() -> TextAnimation { binding.textProps.animation ?? TextAnimation() }
        func on() -> Bool { binding.textProps.animation != nil }
        func free() -> Bool { binding.textProps.wordStyle == nil }
        func ops(_ next: TextAnimation) -> [ReelOp] {
            binding.ops(text: TextPatch(animation: .some(next)))
        }
        return InspectorSection(
            id: "text.animation", title: "Reveal",
            summary: {
                guard let animation = binding.textProps.animation else { return "off" }
                return animation.kind.displayName.lowercased()
                    + String(format: " · %.2f s", ReelTime.seconds(animation.inDuration))
            },
            note: { free() ? nil : Self.wordStyleNote },
            reset: { binding.apply("Animation", text: TextPatch(animation: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorPopupRow(
                    "Reveal", binding, name: "Text Animation", items: items,
                    read: {
                        guard let kind = binding.textProps.animation?.kind else { return 0 }
                        return (kinds.firstIndex(of: kind) ?? 0) + 1
                    },
                    ops: { index in
                        guard index > 0, kinds.indices.contains(index - 1) else {
                            return binding.ops(text: TextPatch(animation: .some(nil)))
                        }
                        // The durations as they stand: switching the reveal
                        // must not reset the timing the user chose for it.
                        var a = current()
                        a.kind = kinds[index - 1]
                        return ops(a)
                    },
                    mixed: { binding.mixedText { $0.animation?.kind } }, enabled: free),
                inspectorValueRow(
                    "In", binding, name: "Animation In", unit: " s", decimals: 2, min: 0, max: 10,
                    quick: [0, 0.25, 0.5, 1, 2],
                    read: { ReelTime.seconds(current().inDuration) },
                    ops: { value in
                        var a = current()
                        a.inDuration = binding.frameTicks(seconds: value)
                        return ops(a)
                    },
                    mixed: { binding.mixedText { $0.animation?.inDuration } },
                    enabled: { on() && free() }),
                inspectorValueRow(
                    "Out", binding, name: "Animation Out", unit: " s", decimals: 2, min: 0,
                    max: 10, quick: [0, 0.25, 0.5, 1, 2],
                    read: { ReelTime.seconds(current().outDuration) },
                    ops: { value in
                        var a = current()
                        a.outDuration = binding.frameTicks(seconds: value)
                        return ops(a)
                    },
                    mixed: { binding.mixedText { $0.animation?.outDuration } },
                    enabled: { on() && free() }),
            ])
    }

    // MARK: Presets

    /// The four one-click looks of §4.3. A preset is two patches — the face
    /// and backdrop (text) plus where the box sits (video) — committed as ONE
    /// undo step, and it routes through the binding like everything else, so
    /// applying one inside an action sets that action's end state.
    func presetSection() -> InspectorSection {
        var buttons: [NSView] = []
        for preset in TextPreset.all {
            buttons.append(
                OptionButtonControl(
                    title: preset.name,
                    action: { [weak self] in self?.apply(preset) },
                    enabled: { true }, onEdit: {}))
        }
        return InspectorSection(
            id: "text.presets", title: "Presets",
            defaultExpanded: false,
            rows: [
                inspectorButtonRow(Array(buttons.prefix(2))),
                inspectorButtonRow(Array(buttons.dropFirst(2))),
            ])
    }

    private func apply(_ preset: TextPreset) {
        let canvas = binding.canvas
        let patches = preset.patches(on: CGSize(width: canvas.width, height: canvas.height))
        binding.apply(
            preset.name, binding.ops(text: patches.text) + binding.ops(video: patches.video))
    }
}

// MARK: - Presets

/// One text preset (§4.3). Sizes and positions are FRACTIONS of the canvas so
/// a preset means the same thing on a 4K canvas as on a vertical one: a size
/// of the canvas's SHORT side, a position of its width and height (spec §11
/// VR-41), so a tall canvas gets the line height a wide one has.
struct TextPreset {
    let name: String
    let font: String
    let sizeFraction: Double
    let xFraction: Double
    let yFraction: Double
    let align: String
    let backdrop: BackdropProps?
    /// Of H, on a canvas taller than wide, in place of `yFraction` (the Caption
    /// row's 0.25, VR-41); nil keeps `yFraction` on every canvas.
    var tallYFraction: Double? = nil

    /// The font size on `canvas`: `sizeFraction` of `min(W, H)`. On a canvas at
    /// least as wide as tall that is H, so the old `H × sizeFraction` is kept to the bit.
    func size(on canvas: CGSize) -> Double {
        (sizeFraction * Double(min(canvas.width, canvas.height))).rounded()
    }

    /// Where the box's centre sits on `canvas`.
    func position(on canvas: CGSize) -> (x: Double, y: Double) {
        let y = canvas.height > canvas.width ? tallYFraction ?? yFraction : yFraction
        return (xFraction * Double(canvas.width), y * Double(canvas.height))
    }

    /// Text ▸ Presets' two patches: the face, size, alignment and backdrop, and where the
    /// box sits at full opacity.
    func patches(on canvas: CGSize) -> (text: TextPatch, video: VideoPatch) {
        let at = position(on: canvas)
        return (
            TextPatch(
                font: font, size: size(on: canvas), align: align, valign: "middle",
                backdrop: .some(backdrop)),
            VideoPatch(x: at.x, y: at.y, opacity: 1)
        )
    }

    static let all: [TextPreset] = [
        TextPreset(
            name: "Title", font: "SourceSans3-Bold", sizeFraction: 0.09, xFraction: 0,
            yFraction: 0, align: "center", backdrop: nil),
        TextPreset(
            name: "Subtitle", font: "SourceSans3-SemiBold", sizeFraction: 0.05, xFraction: 0,
            yFraction: 0.18, align: "center", backdrop: nil),
        TextPreset(
            name: "Lower Third", font: "SourceSans3-SemiBold", sizeFraction: 0.045,
            xFraction: -0.2, yFraction: 0.28, align: "left",
            backdrop: BackdropProps(color: [0, 0, 0, 0.55], padding: 18, radius: 6)),
        TextPreset(
            name: "Caption", font: "SourceSans3-Regular", sizeFraction: 0.035, xFraction: 0,
            yFraction: 0.38, align: "center",
            backdrop: BackdropProps(color: [0, 0, 0, 0.6], padding: 12, radius: 8),
            tallYFraction: 0.25),
    ]
}

// MARK: - Faces

/// The model's one font string ↔ the panel's family + style pair.
///
/// Everything here tolerates a name this machine has no font for: a project
/// carries PostScript names, and the Text tab still has to open (and still has
/// to be able to change the face) on a machine missing that family.
enum TextFace {
    /// Installed families, sorted. Read once — `availableFontFamilies` walks
    /// the font registry, and this popup is rebuilt on every selection change.
    static let families: [String] = NSFontManager.shared.availableFontFamilies.sorted()

    /// One member of a family: its PostScript name and the style label.
    struct Member {
        let name: String
        let style: String
    }

    static func members(of family: String) -> [Member] {
        let raw = NSFontManager.shared.availableMembers(ofFontFamily: family) ?? []
        return raw.compactMap { entry in
            guard entry.count >= 2, let name = entry[0] as? String,
                  let style = entry[1] as? String
            else { return nil }
            return Member(name: name, style: style)
        }
    }

    /// The family a stored PostScript name belongs to; the first installed
    /// family when the font is missing, so the popup always has a row.
    static func family(of postScriptName: String) -> String {
        if let font = NSFont(name: postScriptName, size: 12), let family = font.familyName {
            return family
        }
        return families.first ?? "Helvetica"
    }

    /// The style label of a stored name ("SemiBold"), or "Regular".
    static func style(of postScriptName: String) -> String {
        let family = family(of: postScriptName)
        return members(of: family).first { $0.name == postScriptName }?.style ?? "Regular"
    }

    /// The PostScript name for a family plus a style label, keeping the style
    /// across a family change when the new family has one by that name.
    static func postScriptName(family: String, style: String) -> String {
        let list = members(of: family)
        if let match = list.first(where: { $0.style == style }) { return match.name }
        if let regular = list.first(where: { $0.style == "Regular" }) { return regular.name }
        return list.first?.name ?? family
    }
}

import AppKit

/// The Clip tab's SHAPE sections (spec §4.3): kind, stroke, fill, gradient,
/// arrowheads and corner radius.
///
/// **This pane is never shown**: since the six tabs became three it is a
/// factory `ClipPane` holds and calls, right after Transform, when EVERY
/// selected clip is a shape clip. The shared Shadow group is not in the list
/// any more — it writes `video.shadow`, so the Clip tab carries it once, in
/// the effects group.
///
/// Shapes are described, never rasterized, in the model (§11), so every
/// control here is one `set_shape` patch — and unlike Video/Audio/Text there
/// is no action form, because §5.4's patch covers those three only.
final class ShapePane: InspectorPaneView {
    /// Whether the shape sections apply: they write `set_shape`, which errors
    /// on any other kind, so a mixed selection gets none of them.
    var allShape: Bool {
        !binding.clips.isEmpty && binding.shapeClips.count == binding.clips.count
    }

    /// The kind decides which controls mean anything (a line has no fill, a
    /// box has no endpoints), so it belongs in the rebuild signature — and so
    /// does the number of gradient stops, because that is a number of ROWS.
    /// `-1` for "no gradient at all" rather than 0: a gradient the core would
    /// refuse for having no stops is still a different panel from none.
    override var structureSignature: String {
        super.structureSignature + "|" + binding.shapeProps.kind.rawValue + "|"
            + "\(binding.shapeProps.gradient?.stops.count ?? -1)"
    }

    // MARK: Kind and box

    func shapeSection() -> InspectorSection {
        let binding = self.binding
        let kinds = ShapeKind.allCases
        return InspectorSection(
            id: "shape.kind", title: "Shape",
            summary: { binding.shapeProps.kind.displayName.lowercased() },
            reset: { binding.apply("Shape", shape: ShapePatch(radius: 0)) },
            differs: { binding.shapeProps.radius != 0 },
            rows: [
                inspectorPopupRow(
                    "Kind", binding, name: "Shape Kind", items: kinds.map { $0.displayName },
                    read: { kinds.firstIndex(of: binding.shapeProps.kind) ?? 0 },
                    ops: { index in
                        guard kinds.indices.contains(index) else { return [] }
                        return binding.ops(shape: ShapePatch(kind: kinds[index]))
                    },
                    mixed: { binding.mixedShape { $0.kind } }),
                inspectorValueRow(
                    "Width", binding, name: "Shape Size", unit: " px", decimals: 0, min: 1,
                    max: 20000, slider: false,
                    read: { binding.shapeProps.width },
                    ops: { binding.ops(shape: ShapePatch(width: $0)) },
                    mixed: { binding.mixedShape { $0.width } }),
                inspectorValueRow(
                    "Height", binding, name: "Shape Size", unit: " px", decimals: 0, min: 1,
                    max: 20000, slider: false,
                    read: { binding.shapeProps.height },
                    ops: { binding.ops(shape: ShapePatch(height: $0)) },
                    mixed: { binding.mixedShape { $0.height } }),
                inspectorValueRow(
                    "Corner radius", binding, name: "Shape Radius", unit: " px", decimals: 0,
                    min: 0, max: 2000, quick: [0, 4, 8, 16, 32, 64],
                    read: { binding.shapeProps.radius },
                    ops: { binding.ops(shape: ShapePatch(radius: $0)) },
                    mixed: { binding.mixedShape { $0.radius } },
                    // A radius only rounds a rectangle (§5.2).
                    enabled: { binding.shapeProps.kind == .rectangle }),
            ])
    }

    // MARK: Stroke

    func strokeSection() -> InspectorSection {
        let binding = self.binding
        func current() -> StrokeProps { binding.shapeProps.stroke ?? StrokeProps() }
        func on() -> Bool { binding.shapeProps.stroke != nil }
        return InspectorSection(
            id: "shape.stroke", title: "Stroke",
            summary: { on() ? String(format: "%.1f px", current().width) : "off" },
            reset: { binding.apply("Stroke", shape: ShapePatch(stroke: .some(StrokeProps()))) },
            differs: { binding.shapeProps.stroke.map { $0 != StrokeProps() } ?? false },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Stroke", binding, name: "Stroke", read: on,
                    ops: { value in
                        binding.ops(
                            shape: ShapePatch(stroke: value ? .some(StrokeProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedShape { $0.stroke != nil } }),
                inspectorValueRow(
                    "Width", binding, name: "Stroke Width", unit: " px", decimals: 1, min: 0.5,
                    max: 200, quick: [1, 2, 4, 6, 12, 24],
                    read: { current().width },
                    ops: { value in
                        var s = current()
                        s.width = value
                        return binding.ops(shape: ShapePatch(stroke: .some(s)))
                    },
                    mixed: { binding.mixedShape { $0.stroke?.width } },
                    enabled: on),
                inspectorColorRow(
                    "Color", binding, name: "Stroke Color", read: { current().color },
                    ops: { color in
                        var s = current()
                        s.color = color
                        return binding.ops(shape: ShapePatch(stroke: .some(s)))
                    },
                    mixed: { binding.mixedShape { $0.stroke?.color } },
                    enabled: on),
            ])
    }

    // MARK: Fill

    /// The fill's opacity IS its alpha channel — the model has one colour per
    /// fill, not a colour plus an opacity — so the slider rewrites the fourth
    /// component and leaves the other three alone.
    func fillSection() -> InspectorSection {
        let binding = self.binding
        func current() -> RGBA { binding.shapeProps.fill ?? [1, 1, 1, 1] }
        func on() -> Bool { binding.shapeProps.fill != nil }
        func alpha() -> Double { current().count >= 4 ? current()[3] : 1 }
        return InspectorSection(
            id: "shape.fill", title: "Fill",
            summary: { on() ? String(format: "%.0f%%", alpha() * 100) : "off" },
            reset: { binding.apply("Fill", shape: ShapePatch(fill: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Fill", binding, name: "Fill", read: on,
                    ops: { value in
                        binding.ops(shape: ShapePatch(fill: value ? .some([1, 1, 1, 1]) : .some(nil)))
                    },
                    mixed: { binding.mixedShape { $0.fill != nil } }),
                inspectorColorRow(
                    "Color", binding, name: "Fill Color", read: current,
                    ops: { binding.ops(shape: ShapePatch(fill: .some($0))) },
                    mixed: { binding.mixedShape { $0.fill } },
                    enabled: on),
                inspectorValueRow(
                    "Opacity", binding, name: "Fill Opacity", unit: "%", decimals: 0, min: 0,
                    max: 100, quick: [0, 25, 50, 75, 100],
                    read: { alpha() * 100 },
                    ops: { value in
                        var color = current()
                        while color.count < 4 { color.append(1) }
                        color[3] = value / 100
                        return binding.ops(shape: ShapePatch(fill: .some(color)))
                    },
                    mixed: { binding.mixedShape { $0.fill?.last } },
                    enabled: on),
            ])
    }

    // MARK: Gradient

    /// The gradient fill (§5.2's `shape.gradient`, format version 6): a
    /// geometry, an angle and the stops, all of it one `set_shape` patch.
    ///
    /// Three rules out of the schema show up here as UI, and none of them is
    /// this file's invention:
    ///
    ///  - **Every write sends the WHOLE object.** The core MERGES a nested
    ///    object into a stored one key by key (§5.2), but a stored `null` is
    ///    not an object: `actions::merge` replaces it with what the patch
    ///    carries, and the keys left out then come from `Gradient::default()`
    ///    rather than from what the clip had. This section is where a
    ///    gradient is turned ON from null, so it sends every key and is right
    ///    in both cases. `shadow` has carried that since M3 and `obscure`
    ///    since phase 3; `edited` below is where `gradient` joins them.
    ///  - **The Fill rows above stay live.** A gradient takes precedence over
    ///    `fill` and does not clear it, which is what makes this section's
    ///    Reset — one `{gradient: null}` — an exact inverse rather than a
    ///    shape that goes invisible. Disabling the colour underneath would
    ///    hide the value the Reset is about to bring back, so the note says
    ///    where the fill went instead of the panel pretending it is gone.
    ///  - **`line` and `arrow` get the rows DISABLED, not hidden.** The field
    ///    is stored and range-checked on every kind and read by the two area
    ///    kinds alone — `radius`'s precedent exactly — so flipping the Kind
    ///    popup to Line and back may not lose the ramp.
    func gradientSection() -> InspectorSection {
        let binding = self.binding
        let kinds = GradientKind.allCases
        func current() -> Gradient? { binding.shapeProps.gradient }
        func on() -> Bool { current() != nil }
        /// Whether this kind has an interior to fill at all.
        func area() -> Bool { !binding.shapeProps.kind.isLinear }
        func list() -> [GradientStop] { current()?.stops ?? [] }
        func at(_ index: Int) -> GradientStop? {
            let stops = list()
            return stops.indices.contains(index) ? stops[index] : nil
        }
        func ops(_ next: Gradient?) -> [ReelOp] {
            binding.ops(shape: ShapePatch(gradient: .some(next)))
        }
        /// The gradient with `change` applied and the other keys as they
        /// stand. This is the "send it whole" rule above, spelled once so that
        /// no row has to remember it.
        func edited(_ change: (inout Gradient) -> Void) -> [ReelOp] {
            guard var gradient = current() else { return [] }
            change(&gradient)
            return ops(gradient)
        }
        func edited(replacing index: Int, _ stop: GradientStop) -> [ReelOp] {
            var next = list()
            guard next.indices.contains(index) else { return [] }
            next[index] = stop
            return edited { $0.stops = next }
        }
        /// The mixed badge for one stop's field: a selection where some clip
        /// has no gradient, or none at that index, disagrees — which the
        /// `nil` says, the way `obscureSection`'s `mixedAt` says it.
        func mixedAt<T: Equatable>(_ index: Int, _ read: @escaping (GradientStop) -> T) -> Bool {
            binding.mixedShape { props -> T? in
                guard let stops = props.gradient?.stops, stops.indices.contains(index)
                else { return nil }
                return read(stops[index])
            }
        }
        /// The colour half way between two stops, component by component —
        /// which is exactly what `CGGradient` does between them, in the same
        /// sRGB space, so a handle added here sits ON the ramp rather than
        /// beside it. A three-component colour is an opaque one (`RGBA`'s own
        /// rule), so both are padded the same way before they are mixed.
        func midpoint(_ a: RGBA, _ b: RGBA) -> RGBA {
            func component(_ color: RGBA, _ index: Int) -> Double {
                index < color.count ? color[index] : (index == 3 ? 1 : 0)
            }
            return (0..<4).map { (component(a, $0) + component(b, $0)) / 2 }
        }
        /// A stop dropped into the WIDEST gap and coloured by the ramp that
        /// is already there, so Add changes the picture not at all: it puts a
        /// handle where the ramp already runs, which is what Add means in
        /// every gradient editor. The model cannot do this for you —
        /// `GradientStop`'s own default is black at 0, because serde has to
        /// fill a missing key without knowing which row was clicked.
        ///
        /// It inserts into the list as it is HELD, never into the sorted one.
        /// The rows are drawn in held order and the core deliberately does
        /// not police that order (`props_check.rs` argues the missing check
        /// where it would have gone), so sorting here would make every row
        /// jump the first time somebody pressed Add.
        func added(_ stops: [GradientStop]) -> [GradientStop] {
            guard stops.count >= 2 else { return Gradient.defaultStops }
            let ramp = stops.enumerated().sorted {
                $0.element.at == $1.element.at
                    ? $0.offset < $1.offset : $0.element.at < $1.element.at
            }
            var widest = -1.0
            var left = ramp[0]
            var right = ramp[1]
            for (a, b) in zip(ramp, ramp.dropFirst()) where b.element.at - a.element.at > widest {
                widest = b.element.at - a.element.at
                left = a
                right = b
            }
            var next = stops
            next.insert(
                GradientStop(
                    at: (left.element.at + right.element.at) / 2,
                    color: midpoint(left.element.color, right.element.color)),
                at: left.offset + 1)
            return next
        }

        var rows: [NSView] = [
            inspectorCheckRow(
                "Gradient", binding, name: "Gradient", read: on,
                ops: { value in ops(value ? Gradient() : nil) },
                mixed: { binding.mixedShape { $0.gradient != nil } },
                enabled: area),
            inspectorPopupRow(
                "Kind", binding, name: "Gradient Kind", items: kinds.map { $0.displayName },
                read: { kinds.firstIndex(of: current()?.kind ?? .linear) ?? 0 },
                ops: { index in
                    guard kinds.indices.contains(index) else { return [] }
                    return edited { $0.kind = kinds[index] }
                },
                mixed: { binding.mixedShape { $0.gradient?.kind } },
                enabled: { on() && area() }),
            // Degrees from the RIGHT, counter-clockwise, and the same eight
            // quick picks the shadow's angle gets, because it is the same
            // convention and the crate has only the one.
            inspectorValueRow(
                "Angle", binding, name: "Gradient Angle", unit: "°", decimals: 0, min: 0,
                max: 360, quick: [0, 45, 90, 135, 180, 225, 270, 315],
                read: { current()?.angle ?? 0 },
                ops: { v in edited { $0.angle = v } },
                mixed: { binding.mixedShape { $0.gradient?.angle } },
                // A radial gradient has no direction to point: the model
                // stores the angle through the flip all the same, so coming
                // back to Linear finds the number where it was left.
                enabled: { on() && area() && current()?.kind == .linear }),
        ]
        for index in 0..<list().count {
            let swatch = OptionSwatchControl(
                read: { at(index)?.color.nsColor ?? .black },
                write: { color in
                    guard let stop = at(index),
                        let next = changedRGBA(color, from: stop.color)
                    else { return }
                    binding.apply(
                        "Gradient Stop",
                        edited(replacing: index, GradientStop(at: stop.at, color: next)))
                },
                enabled: area, onEdit: {})
            // A stop's position is 0–1 in the model and a PERCENTAGE here,
            // for `video.opacity`'s reason: the ramp is a distance across the
            // box, and nobody reads 0.35 of a box as a third of the way.
            let position = OptionFieldControl(
                width: InspectorMetrics.fieldWidth, unit: "%", decimals: 0, min: 0, max: 100,
                quick: [0, 25, 50, 75, 100],
                read: { (at(index)?.at ?? 0) * 100 },
                write: { value in
                    guard let stop = at(index) else { return }
                    binding.apply(
                        "Gradient Stop",
                        edited(replacing: index, GradientStop(at: value / 100, color: stop.color)))
                },
                enabled: area,
                onEdit: { binding.edited() })
            let remove = OptionButtonControl(
                title: "Remove",
                action: {
                    var next = list()
                    guard next.count > 2, next.indices.contains(index) else {
                        NSSound.beep()
                        return
                    }
                    next.remove(at: index)
                    binding.apply("Remove Stop", edited { $0.stops = next })
                },
                enabled: { area() && list().count > 2 }, onEdit: {})
            remove.toolTip =
                "Take this colour off the ramp — two stops is the floor, because one "
                + "colour is a fill and Fill above already spells that"
            rows.append(
                inspectorRow(
                    "Stop \(index + 1)", [swatch, position, remove],
                    mixed: { mixedAt(index) { $0.color } || mixedAt(index) { $0.at } }))
        }
        if !on() {
            rows.append(inspectorRow(nil, [InspectorRowLabel("No gradient.")]))
        }
        let add = OptionButtonControl(
            title: "Add Stop",
            action: {
                let next = added(list())
                guard next.count > list().count else {
                    NSSound.beep()
                    return
                }
                binding.apply("Add Stop", edited { $0.stops = next })
            },
            enabled: { area() && on() && list().count < Gradient.maxStops }, onEdit: {})
        add.toolTip =
            "Put a handle on the ramp where the ramp already is — the widest gap, "
            + "at the colour that is already there"
        rows.append(inspectorButtonRow([add, InspectorRowLabel("\(Gradient.maxStops) at most")]))

        return InspectorSection(
            id: "shape.gradient", title: "Gradient",
            summary: {
                guard let gradient = current() else { return "off" }
                return "\(gradient.kind.displayName.lowercased()), \(gradient.stops.count) stops"
            },
            note: {
                guard area() else {
                    return "Fills the rectangle or ellipse; a line or arrow keeps its "
                        + "stroke colour."
                }
                guard on(), binding.shapeProps.fill != nil else { return nil }
                return "The gradient covers the Fill colour above; Reset brings it back."
            },
            reset: { binding.apply("Gradient", shape: ShapePatch(gradient: .some(nil))) },
            defaultExpanded: false,
            rows: rows)
    }

    // MARK: Arrowheads

    func arrowSection() -> InspectorSection {
        let binding = self.binding
        /// Arrowheads only mean something on the two linear kinds, whose
        /// geometry is the `from`/`to` endpoints (§5.2).
        func linear() -> Bool { binding.shapeProps.kind.isLinear }
        return InspectorSection(
            id: "shape.arrows", title: "Arrowheads",
            summary: {
                let props = binding.shapeProps
                switch (props.arrowStart, props.arrowEnd) {
                case (true, true): return "both"
                case (true, false): return "start"
                case (false, true): return "end"
                case (false, false): return "none"
                }
            },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Arrowhead at start", binding, name: "Arrowhead",
                    read: { binding.shapeProps.arrowStart },
                    ops: { binding.ops(shape: ShapePatch(arrowStart: $0)) },
                    mixed: { binding.mixedShape { $0.arrowStart } },
                    enabled: linear),
                inspectorCheckRow(
                    "Arrowhead at end", binding, name: "Arrowhead",
                    read: { binding.shapeProps.arrowEnd },
                    ops: { binding.ops(shape: ShapePatch(arrowEnd: $0)) },
                    mixed: { binding.mixedShape { $0.arrowEnd } },
                    enabled: linear),
            ])
    }
}
//! The shape vocabulary — [`ShapeProps`], the [`ShapeKind`] it draws, the
//! [`Stroke`] around it and the [`Gradient`] (with [`GradientKind`],
//! [`GradientStop`] and the [`MAX_GRADIENT_STOPS`] budget on it) that fills
//! it.
//!
//! Cut out of `model_props.rs` in road map 5's E2, when that file stood AT
//! the 600-line cap owing `video.motion`, and cut HERE because
//! `model_text.rs` is its own precedent: a whole property group moved out
//! with the types only it names. Text and shape are the two CPU-rendered,
//! hash-keyed sources — neither reaches the fragment stage as a sampled
//! texture the model describes, both are drawn by
//! `LayerRenderers`/`LayerRenderersText` into one, and both are keyed by
//! the recipe's content hash — so taking the second after the first leaves
//! `model_props.rs` holding what the compositor's uniform block is read
//! from and nothing else. Nothing here is ever a shader discriminant, and
//! that is a standing rule rather than an omission: [`GradientKind`]'s own
//! doc says a kind may be added at the END and that nothing derives a
//! number from the order, where [`crate::model::BlendMode`]'s order IS the
//! discriminant.
//!
//! Re-exported whole by `model_props.rs`, which `model.rs` re-exports whole
//! in turn, so `crate::model::ShapeProps` and every other path is
//! unchanged. The FIELD that holds these values (`Clip.shape`) stays in
//! `model.rs` with the clip's other property groups.
//!
//! The rules are `model.rs`'s: the field names ARE the JSON keys,
//! declaration order IS key order, every type is `#[serde(default)]` over a
//! hand-written [`Default`] that says what an absent key means, and nothing
//! here carries `deny_unknown_fields`.

use serde::{Deserialize, Serialize};

use crate::model::Color;

/// A shape layer. A rounded rectangle is [`ShapeKind::Rectangle`] with a
/// non-zero `radius`; `from`/`to` are unit coordinates inside the box and
/// apply to lines and arrows only (spec §5.2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct ShapeProps {
    pub kind: ShapeKind,
    pub width: f64,
    pub height: f64,
    pub stroke: Option<Stroke>,
    pub fill: Option<Color>,
    pub arrow_start: bool,
    pub arrow_end: bool,
    pub radius: f64,
    pub from: [f64; 2],
    pub to: [f64; 2],
    /// A gradient fill, taking precedence over `fill` when set
    /// (format version 6). Ignored on `Line` and `Arrow`, which have no
    /// area.
    pub gradient: Option<Gradient>,
}

impl Default for ShapeProps {
    /// The spec §5.2 example's box, stroked and unfilled so a newly added
    /// shape is visible over any footage.
    fn default() -> Self {
        ShapeProps {
            kind: ShapeKind::Rectangle,
            width: 320.0,
            height: 120.0,
            stroke: Some(Stroke::default()),
            fill: None,
            arrow_start: false,
            arrow_end: false,
            radius: 0.0,
            from: [0.0, 1.0],
            to: [1.0, 0.0],
            gradient: None,
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ShapeKind {
    #[default]
    Rectangle,
    Ellipse,
    Line,
    Arrow,
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Stroke {
    pub width: f64,
    pub color: Color,
}

impl Default for Stroke {
    fn default() -> Self {
        Stroke {
            width: 6.0,
            color: [1.0, 1.0, 1.0, 1.0],
        }
    }
}

/// The most stops one gradient may carry. NOT a shader budget, which is why
/// it is 8 where [`crate::model::MAX_FILTERS`] and
/// [`crate::model::MAX_OBSCURE`] are both 4: those two are SLOTS — the uniform block carries exactly four `(kind, amount)` pairs
/// and exactly four regions, and a fifth of either has nowhere to go — while
/// a gradient never reaches the fragment stage at all, since
/// `LayerRenderers.renderShape` hands the stops to `CGGradient` on the CPU,
/// which takes as many as it is given. Four here would be a real limitation
/// (a sunset, a spectrum, a brand ramp) bought for no technical reason, and
/// a cap that turns out too high costs nothing where one that turns out too
/// low is reported as a bug. It is NAMED rather than trimmed all the same,
/// the posture the other two take: a stop silently dropped from the next
/// write is a colour the user placed and can no longer see.
pub const MAX_GRADIENT_STOPS: usize = 8;

/// A gradient fill for a shape (format version 6, road map 2's phase 6) —
/// what `shape.fill`'s single colour becomes when a flat plate is not
/// enough: a sky behind a title, a brand ramp, the wash on the full-canvas
/// background clip `edit_background.rs` puts on the back track.
///
/// **Setting a gradient does not clear `fill`.** Both persist and the
/// RENDERER prefers the gradient while it is non-null, which makes
/// `{"gradient": null}` an exact inverse — the inspector's Reset restores
/// the colour underneath rather than leaving an invisible shape — and keeps
/// the precedence rule in one statable place instead of spreading it as a
/// side effect of whichever op wrote last. The stops are NOT required to be
/// sorted, and that too is a decision rather than an omission:
/// `props_check.rs` argues the missing check where it would have gone, and
/// the renderer sorts.

### Move, scale and rotate

| Gesture | What it does |
|---|---|
| Drag inside the box | Move. Every selected clip moves by the same amount |
| ← → ↑ ↓ (canvas focused) | Nudge the selection 1 canvas pixel |
| ⇧ + arrow | Nudge 10 pixels |
| Drag one of the eight square handles | Scale (see below) |
| ⌥ while scaling | Scale about the centre instead of pinning the opposite handle |
| Drag the round grip above the top edge | Rotate about the clip's centre |
| ⇧ while rotating | Snap the angle to 15° steps |
| Esc during any drag | Cancel the drag and put the clip back where it was, with no undo step |

How a scale drag behaves depends on the clip:

- **Video, image, still, graphic and nest clips** have one uniform scale. Every
  handle scales the whole picture and keeps its aspect ratio.
- **Shape clips** change their box size instead. A corner handle keeps the
  aspect ratio and ⇧ frees it. An edge handle changes only the width or only
  the height.
- **Text clips**: the left and right edge handles set the text box's wrap
  width, which makes the box fixed-width. The corners and the top and bottom
  edges scale the text uniformly.

A drag scales between 1 % and 1000 %. Each drag is one undo step, and a click
that doesn't move anything adds no step.

There is no separate anchor-point control. Rotation, the Picture tab's Scale
field and a ⌥ scale drag pivot on the centre of the clip's uncropped picture.
A plain handle drag keeps the opposite handle in place by moving the clip as
it scales.

### Line and arrow endpoints

A line or arrow shape has a round handle at each end. Drag a handle to move
that end. The scale handles and the rotation grip still work on the line's
box.

## Text clips

Press **T**, or use the timeline bar's **Add Text** button, to add a text clip
at the playhead. It goes on the front-most track if there is room, or on a new
track in front of everything if there isn't. The new clip:

- reads "Title" in Source Sans 3 Bold at 72 px, white, centred
- lasts 5 seconds
- is selected, so the **Text** sub-tab opens on it

A text clip has no source file, so you can trim it to any length.
Double-click it on the canvas to type (see
[Inline text editing](#inline-text-editing)).

*Agents:* `add_text_clip` (track, at, optional duration and text, either a
plain string or a text patch); `set_text` to restyle.

### The Text tab

| Section | Rows |
|---|---|
| **Content** | A multi-line text area. Return, Tab or a click away applies it and gives the keys back to the editor; ⇧Return, ⌘Return, ⌥Return or ⌃Return starts a new line |
| **Font** | **Family** (every font installed on the Mac, plus the faces the app ships with: Source Sans 3, Source Serif 4, Montserrat, Anton, Bebas Neue, Darker Grotesque and IBM Plex Mono), **Style** (that family's faces), **Size** 6–800 px |
| **Style** | **Color**, **Align** (L / C / R), **Vertical** (top / middle / bottom within the box), **UPPERCASE**, **Line spacing** 0.5–4× (default 1), **Tracking** −20 to 100 px (default 0) |
| **Outline** | **Outline** on/off, **Width** 0–40 px (default 2), **Color** (default black) |
| **Backdrop** | A plate behind the text: **Backdrop** on/off, **Fill** (default black at 60 %), **Padding** 0–200 px (default 12), **Radius** 0–200 px (default 8) |
| **Box** | **Mode**: **Auto-size** (the box fits the words) or **Fixed width** (the words wrap). **Width** is 20–20000 px, starting at 60 % of the canvas width |
| **Reveal** | How the text arrives and leaves: **None**, **Typewriter**, **Word Fade** or **Line Rise**, with separate **In** and **Out** durations (0–10 s; In defaults to 1 s and Out to 0) measured from the clip's first and last frame |
| **Presets** | One-click looks, described below |

UPPERCASE changes only how the text is drawn: what you typed is kept as typed.
A text clip also gets the Picture tab's Transform, Shadow, Filters,
Reflection, Spotlight and Obscure sections.

Every frame of a reveal is worked out by the same calculation for the
preview, a rendered frame and an export, so the three always agree. A text
clip made by word captions has a word style, and while it does, the Reveal
section is greyed with "Word style wins; the reveal does not apply." (see
[Captions](captions.md)).

### Text presets

Each preset sets the face, size, alignment, backdrop and position in one
undo step. It also sets **Vertical** to middle and **Opacity** back to 100 %.
Sizes are fractions of the canvas's shorter side and positions fractions of
its width and height, so a preset fits any canvas size and a vertical canvas
gets the same text height as a horizontal one. On a canvas taller than wide
the Caption preset sits higher, a quarter of the height below centre, clear of
a phone's on-screen controls. With an action selected on the action lane, a
preset sets that action's end state, like any other field.

| Preset | Face | Size (of the shorter side) | Placement | Backdrop |
|---|---|---|---|---|
| Title | Source Sans 3 Bold | 9 % | centred | none |
| Subtitle | Source Sans 3 SemiBold | 5 % | centred, 18 % of the height below centre | none |
| Lower Third | Source Sans 3 SemiBold | 4.5 % | left-aligned, left of centre and low | black at 55 %, padding 18, radius 6 |
| Caption | Source Sans 3 Regular | 3.5 % | centred, 38 % of the height below centre (a quarter on a tall canvas) | black at 60 %, padding 12, radius 8 |

## Shape clips

Click the timeline bar's **Add Shape** button and pick **Rectangle**,
**Ellipse**, **Line** or **Arrow**. Like text, the shape goes on the front-most
track if there is room, lasts 5 seconds, can be trimmed to any length, and
opens on the **Shape** sub-tab.

A new shape is a 320 × 120 box with a 6 px white stroke and no fill, so it
shows up over any footage. A new arrow has its head at the end turned on. A
new line or arrow runs diagonally across its box. A rounded rectangle is a
Rectangle with a corner radius, not a separate kind.

*Agents:* `add_shape_clip` (track, at, optional duration and shape, either a
kind name or a shape patch); `set_shape` for geometry and paint.

### The Shape tab

| Section | Rows |
|---|---|
| **Shape** | **Kind** (Rectangle, Ellipse, Line, Arrow), **Width** and **Height** 1–20000 px, **Corner radius** 0–2000 px (rectangles only) |
| **Stroke** | **Stroke** on/off, **Width** 0.5–200 px (default 6), **Color** (default white) |
| **Fill** | **Fill** on/off (white when first turned on), **Color**, **Opacity** 0–100 % |
| **Gradient** | Fills the shape with a colour ramp in place of the flat fill (below) |
| **Arrowheads** | **Arrowhead at start**, **Arrowhead at end** (lines and arrows only) |

A shape also gets the Picture tab's Transform, Shadow, Filters, Reflection,
Spotlight and Obscure sections.

### Gradients

Tick **Gradient** to fill a rectangle or ellipse with a colour ramp. A new
gradient is **Linear**, black to white, at 0°.

- **Kind**: **Linear** or **Radial**.
- **Angle**: 0–360°, linear only. 0° runs to the right and the angle turns
  counter-clockwise.
- **Stop N** rows: a colour swatch, a position (0–100 % along the ramp) and
  **Remove**. A gradient keeps at least two stops.
- **Add Stop** puts a new stop in the middle of the widest gap, in the colour
  the ramp already has there. A gradient can have up to **eight** stops.

Past the first and last stops, the end colours continue to the shape's edge.
While a gradient is on it covers the Fill colour, and the section says so.
Reset turns the gradient off and brings the flat fill back. Lines and arrows
have no area to fill: the Gradient section is greyed for them and they keep
their stroke colour.

### Animated colours

When an action changes a colour (the text colour, its outline or backdrop, a
word-caption colour, the drop shadow or the chroma key colour), the colour
blends through the OKLab colour space. This avoids the muddy midpoint a
straight RGB blend gives. See [Motion and transitions](motion-and-transitions.md).

Shape colours (stroke, fill and gradient stops) cannot be animated: a
shape's styling always changes the clip itself, even while an action is
selected.

    let base: VideoProps
    /// The uncropped rectangle at mouse-down, un-rotated, canvas space. Its
    /// centre IS the rotation anchor, which is what makes the position
    /// correction below a plain rotation of the centre's displacement.
    let startRect: CGRect
    let rotation: Double

    var scale: Double
    var boxSize: CGSize
    var textWidth: Double
    /// True once a `.textWidth` drag has actually taken the width path. The
    /// other six handles of a text clip fall back to a uniform scale, and
    /// `ops` must then emit `set_video` rather than `set_text`.
    var widthOnly = false
    /// Change in the clip's `(x, y)`, canvas space.
    var offset = CGVector.zero
    var didMove = false

    static let minScale = 0.01
    static let maxScale = 10.0
    static let minBox = 4.0
    static let maxBox = 20000.0

    func ops(to edit: CanvasEditTarget) -> [ReelOp] {
        let placement = VideoPatch(
            x: canvasRound(base.x + offset.dx), y: canvasRound(base.y + offset.dy))
        var uniform = placement
        uniform.scale = canvasRound(scale)
        switch target {
        case .uniform:
            return [edit.op(video: uniform, clip: clip)]
        case .box:
            // Base whatever `edit` says (CI-13): `set_shape` has no action
            // form, and the placement that pins the pivot travels with it.
            return [
                .setShape(
                    clips: [clip],
                    patch: ShapePatch(
                        width: canvasRound(boxSize.width), height: canvasRound(boxSize.height))),
                .setVideo(clips: [clip], patch: placement),
            ]
        case .textWidth:
            guard widthOnly else { return [edit.op(video: uniform, clip: clip)] }
            return [edit.op(text: TextPatch(width: .some(canvasRound(textWidth))), clip: clip)]
        }
    }

    /// `point` is the pointer in canvas space; `aspectFree` is ⇧ and
    /// `aboutCentre` is ⌥.
    mutating func update(point: CGPoint, aspectFree: Bool, aboutCentre: Bool) {
        let centre = CGPoint(x: startRect.midX, y: startRect.midY)
        let grip = handle.point(in: startRect)
        let pivot = aboutCentre ? centre : handle.opposite.point(in: startRect)
        // The pointer, taken back into the layer's own axis-aligned space —
        // the space `startRect` and the handles live in.
        let local = unrotatedPoint(point, about: centre)

        let dx0 = grip.x - pivot.x
        let dy0 = grip.y - pivot.y
        let dx = local.x - pivot.x
        let dy = local.y - pivot.y
        let axisX = abs(dx0) > 0.001 ? dx / dx0 : 1
        let axisY = abs(dy0) > 0.001 ? dy / dy0 : 1
        let square = dx0 * dx0 + dy0 * dy0
        let diagonal = square > 0.001 ? (dx * dx0 + dy * dy0) / square : 1

        var fx: CGFloat = 1
        var fy: CGFloat = 1
        switch target {
        case .uniform:
            let f = handle.isCorner ? diagonal : (handle.drivesX ? axisX : axisY)
            let clamped = min(
                max(base.scale * Double(f), CanvasScaleSession.minScale),
                CanvasScaleSession.maxScale)
            scale = clamped
            let applied = base.scale > 0 ? clamped / base.scale : 1
            fx = CGFloat(applied)
            fy = fx

        case .box(let start):
            var wide = start.width
            var high = start.height
            if handle.isCorner {
                wide = start.width * Double(aspectFree ? axisX : diagonal)
                high = start.height * Double(aspectFree ? axisY : diagonal)
            } else if handle.drivesX {
                wide = start.width * Double(axisX)
            } else {
                high = start.height * Double(axisY)
            }
            boxSize = CGSize(
                width: min(max(wide, CanvasScaleSession.minBox), CanvasScaleSession.maxBox),
                height: min(max(high, CanvasScaleSession.minBox), CanvasScaleSession.maxBox))
            fx = start.width > 0 ? CGFloat(boxSize.width / start.width) : 1
            fy = start.height > 0 ? CGFloat(boxSize.height / start.height) : 1

        case .textWidth(let start):
            guard handle.drivesX, !handle.isCorner else {
                // Corners and the top/bottom edges have no second axis to
                // give a text clip, so they scale it uniformly instead.
                let f = handle.isCorner ? diagonal : axisY
                scale = min(
                    max(base.scale * Double(f), CanvasScaleSession.minScale),
                    CanvasScaleSession.maxScale)
                let applied = base.scale > 0 ? scale / base.scale : 1
                widthOnly = false
                apply(fx: CGFloat(applied), fy: CGFloat(applied), pivot: pivot, centre: centre)
                didMove = true
                return
            }
            widthOnly = true
            textWidth = min(
                max(start * Double(axisX), CanvasScaleSession.minBox),
                CanvasScaleSession.maxBox)
            // The measured box includes backdrop padding and outline
            // overshoot, so the pivot cannot be held exactly; the centre stays
            // put and the text grows both ways.
            offset = .zero
            didMove = true
            return
        }
        apply(fx: fx, fy: fy, pivot: pivot, centre: centre)
        didMove = true
    }

    /// Holds `pivot` still while the box scales by `(fx, fy)`: the centre
    /// moves in the layer's own space, and that displacement is rotated back
    /// into canvas space to become the clip's new `(x, y)`.
    private mutating func apply(fx: CGFloat, fy: CGFloat, pivot: CGPoint, centre: CGPoint) {
        let moved = CGPoint(
            x: pivot.x + (centre.x - pivot.x) * fx,
            y: pivot.y + (centre.y - pivot.y) * fy)
        offset = canvasRotate(
            CGVector(dx: moved.x - centre.x, dy: moved.y - centre.y), degrees: rotation)
    }

    private func unrotatedPoint(_ point: CGPoint, about centre: CGPoint) -> CGPoint {
        let v = canvasUnrotate(
            CGVector(dx: point.x - centre.x, dy: point.y - centre.y), degrees: rotation)
        return CGPoint(x: centre.x + v.dx, y: centre.y + v.dy)
    }
/// overlay through a cache (spec §5.3, §11).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct TextProps {
    pub content: String,
    pub font: String,
    pub size: f64,
    pub color: Color,
    pub align: TextAlign,
    pub valign: TextVAlign,
    /// Multiplier on the font's natural line height.
    pub line_spacing: f64,
    /// Extra letter spacing, in points.
    pub tracking: f64,
    pub outline: Option<Outline>,
    pub backdrop: Option<Backdrop>,
    /// Wrapping width in canvas pixels; `None` lays out on one line.
    pub width: Option<f64>,
    /// How the words arrive and how they leave, or `None` for text that is
    /// simply there for the length of its clip (format version 5).
    pub animation: Option<TextAnimation>,
    /// A transform applied before layout (format version 9); never
    /// changes the token count.
    pub case: TextCase,
    /// One `{start, end}` per whitespace token of `content`, in clip time,
    /// or empty for an untimed text (format version 9, spec §11 W-2).
    pub words: Vec<Word>,
    /// How a timed page shows the word being said, or `None` for a text
    /// that draws its words all alike (format version 9).
    pub word_style: Option<WordStyle>,
}

impl Default for TextProps {
    /// The Title preset: white, centered, at the spec's example font.
    fn default() -> Self {
        TextProps {
